import { Fragment, type ReactNode } from "react";
import { safeHref, cleanBareUrl } from "@/lib/links";

/**
 * Minimal, dependency-free markdown renderer covering the basics used in
 * research posts: headings, lists, blockquotes, bold/italic/inline-code,
 * explicit + bare links, colored text, and paragraphs.
 */

// Curated color spans (`{c:key}text{/c}`) - generated by PostEditor's color
// toolbar buttons, not meant to be hand-typed. Kept to the site's existing
// design tokens rather than allowing arbitrary CSS/inline styles.
const COLOR_CLASS: Record<string, string> = {
  gold: "text-gold-300",
  mint: "text-mint-300",
  red: "text-rose-400",
  blue: "text-sky-400",
};
const COLOR_TAG = /\{c:(gold|mint|red|blue)\}([\s\S]*?)\{\/c\}/;

function inline(text: string, keyBase: string): ReactNode[] {
  const tokens: ReactNode[] = [];
  // [text](url) is matched before bare URLs so it wins; then bare http(s) links.
  // Bold's closing "**" requires a negative lookahead for a further "*" - without
  // it, overlapping bold+italic (e.g. "**hello *world***", from bolding then
  // italicizing part of the same run) stops at the FIRST "**" it finds, which
  // lands mid-run and drops the bold wrapper / leaks stray "*" characters as
  // visible text on the published post. The lookahead makes it prefer the "**"
  // that isn't immediately followed by another star, so "***" tails resolve as
  // "closing italic then bold" instead of "closing bold one star short."
  const regex = /(\{c:(?:gold|mint|red|blue)\}[\s\S]*?\{\/c\}|\*\*[\s\S]+?\*\*(?!\*)|\*[^*]+\*|`[^`]+`|\[[^\]]+\]\([^)]+\)|https?:\/\/[^\s<]+)/g;
  let last = 0;
  let match: RegExpExecArray | null;
  let i = 0;
  while ((match = regex.exec(text))) {
    if (match.index > last) tokens.push(text.slice(last, match.index));
    const t = match[0];
    const key = `${keyBase}-${i++}`;
    if (t.startsWith("{c:")) {
      const m = COLOR_TAG.exec(t);
      if (m) tokens.push(<span key={key} className={COLOR_CLASS[m[1]]}>{inline(m[2], key)}</span>);
    } else if (t.startsWith("**")) tokens.push(<strong key={key}>{inline(t.slice(2, -2), key)}</strong>);
    else if (t.startsWith("`")) tokens.push(<code key={key}>{t.slice(1, -1)}</code>);
    else if (t.startsWith("[")) {
      const m = /\[([^\]]+)\]\(([^)]+)\)/.exec(t);
      if (m) {
        const href = safeHref(m[2]);
        tokens.push(
          href ? (
            <a key={key} href={href} target="_blank" rel="noopener noreferrer">{inline(m[1], key)}</a>
          ) : (
            <span key={key}>{inline(m[1], key)}</span>
          )
        );
      }
    } else if (t.startsWith("http")) {
      // Bare pasted URL → clickable; trailing punctuation kept as plain text.
      const url = cleanBareUrl(t);
      const trailing = t.slice(url.length);
      const href = safeHref(url);
      tokens.push(
        href ? (
          <a key={key} href={href} target="_blank" rel="noopener noreferrer">{url}</a>
        ) : (
          <span key={key}>{url}</span>
        )
      );
      if (trailing) tokens.push(trailing);
    } else if (t.startsWith("*")) tokens.push(<em key={key}>{inline(t.slice(1, -1), key)}</em>);
    last = match.index + t.length;
  }
  if (last < text.length) tokens.push(text.slice(last));
  return tokens;
}

export function Markdown({ content }: { content: string }) {
  const lines = content.replace(/\r\n/g, "\n").split("\n");
  const blocks: ReactNode[] = [];
  let list: string[] = [];
  let key = 0;

  const flushList = () => {
    if (list.length) {
      const items = [...list];
      blocks.push(
        <ul key={`ul-${key++}`}>
          {items.map((it, idx) => (
            <li key={idx}>{inline(it, `li-${key}-${idx}`)}</li>
          ))}
        </ul>
      );
      list = [];
    }
  };

  for (const raw of lines) {
    const line = raw.trimEnd();
    if (/^\s*[-*]\s+/.test(line)) {
      list.push(line.replace(/^\s*[-*]\s+/, ""));
      continue;
    }
    flushList();
    if (!line.trim()) continue;
    if (line.startsWith("### ")) blocks.push(<h3 key={key++}>{inline(line.slice(4), `h3-${key}`)}</h3>);
    else if (line.startsWith("## ")) blocks.push(<h2 key={key++}>{inline(line.slice(3), `h2-${key}`)}</h2>);
    else if (line.startsWith("# ")) blocks.push(<h1 key={key++}>{inline(line.slice(2), `h1-${key}`)}</h1>);
    else if (line.startsWith("> ")) blocks.push(<blockquote key={key++}>{inline(line.slice(2), `bq-${key}`)}</blockquote>);
    else blocks.push(<p key={key++}>{inline(line, `p-${key}`)}</p>);
  }
  flushList();

  return <Fragment>{blocks}</Fragment>;
}
